{"rob":"robolang 1.3;

task bring_boxes(robot r, object b1, object b2, location src1, location src2, location dst) {
    goal { object_at b1 dst; object_at b2 dst; }
    plan {
        move r to src1;
        grasp r b1;
        move r to dst;
        place r b1 at dst;
        move r to src2;
        grasp r b2;
        move r to dst;
        place r b2 at dst;
    }
}
","task":"bring_boxes","bindings":[{"param":"r","id":"arm1"},{"param":"b1","id":"box1"},{"param":"b2","id":"box2"},{"param":"src1","id":"shelf_a"},{"param":"src2","id":"shelf_b"},{"param":"dst","id":"table"}]}
